function test_pn_profile()
% Generated by GitHub Copilot under Lance Lascari's direction.
% Offline extraction/profile tests; generate only in an isolated temporary folder.
pn_directory=fileparts(mfilename('fullpath'));
path_before=path;
directory_before=pwd;
temporary=tempname();
[ok,message]=mkdir(temporary);
assert(ok,message);
cleanup=onCleanup(@() cleanup_test(temporary,path_before,directory_before));
addpath(pn_directory);
script_path=fullfile(temporary,'aa_generate_ros2100_example.m');
[ok,message]=copyfile(fullfile(pn_directory,'aa_generate_ros2100_example.m'),script_path);
assert(ok,message);
% Isolate the fixture from editable interactive plotting/overwrite settings.
script_text=fileread(script_path);
script_text=regexprep(script_text,'(?m)^bSaveData=\d+;','bSaveData=1;');
script_text=regexprep(script_text,'(?m)^bOverwriteData=\d+;','bOverwriteData=0;');
script_text=regexprep(script_text,'(?m)^bPlotData=\d+;','bPlotData=0;');
[file,message]=fopen(script_path,'w');
assert(file~=-1,message);
file_cleanup=onCleanup(@() fclose(file));
assert(fprintf(file,'%s',script_text)==numel(script_text));
clear file_cleanup;
addpath(temporary);
run_example();
saved=load(fullfile(temporary,'datfiles_local','ROS_2100_119_profile.mat'));
profile=saved.pn_profile_s;
validate_pn_profile(profile);
assert(profile.schema_version==1 && numel(profile.points)==21);
assert(profile.representative_index==12);
assert(isequal(saved.pn_struct,profile.points(12)));
assert(isequal(fieldnames(saved.pn_struct),{'fc';'f';'n';'kvco';'comment';'name';'clock'}));
assert(saved.pn_struct.fc==1725e6);
assert(numel(saved.pn_struct.f)==20);
assert(saved.pn_struct.f(1)==1e3 && saved.pn_struct.f(end)==1e6);
assert(isequal(saved.pn_struct.n,[-76.17 -83.67 -89.73 -94.46 -98.27 -101.89 ...
    -105.98 -110.76 -114.58 -118.63 -123.32 -123.14 -124.85 -126.40 ...
    -129.33 -130.42 -134.00 -135.51 -141.41 -143.24]));
expected_kvco=(62.59+(1725-1666.4)/(1727-1666.4)*(62.85-62.59))*1e6;
assert(abs(saved.pn_struct.kvco-expected_kvco)<1e-6);
assert(~isempty(strfind(saved.pn_struct.comment,'DERIVED')));
assert(isequal([profile.points.fc],[1041.5 1094.3 1139.5 1180.5 1257.6 1331 ...
    1403.0 1472.7 1539.5 1604.2 1666.4 1725 1727 1786.5 1843.8 1899.8 ...
    1953.2 2006.2 2055.7 2102.9 2187.1]*1e6));
assert(isequal([profile.points([1:11 13:21]).kvco], ...
    [110.21 93.57 85.25 81.79 77.06 73.60 71.30 68.10 65.02 64 ...
    62.59 62.85 61.06 58.11 56.70 54.02 51.46 47.49 45.18 35.58]*1e6));
assert(isequal(profile.points(13).n,[-76.5 -101.8 -123.1 -143.2]));
must_fail(@run_example,''); % default export protects an existing file

% Exact selection is lossless and preserves the original clock and provenance.
[exact,selection]=select_pn_profile(profile,1725e6);
assert(isequal(exact,saved.pn_struct) && strcmp(selection.mode,'exact'));
legacy=load(fullfile(temporary,'datfiles_local','ROS_2100_119_profile.mat'),'pn_struct');
assert(isequal(legacy.pn_struct,saved.pn_struct));
doubled=mult_div_pn_struct(legacy.pn_struct,2);
assert(doubled.fc==3450e6);
assert(max(abs(doubled.n-legacy.pn_struct.n-20*log10(2)))<1e-12);
combined=add_pn_structs(legacy.pn_struct,legacy.pn_struct);
assert(max(abs(combined.n-legacy.pn_struct.n-10*log10(2)))<1e-12);

% Unequal offset grids: interpolate only inside the intersection, in log offset.
a=build_pn_struct(100,2,[1 10 100],[-10 -20 -30],'a','a');
b=build_pn_struct(200,4,[10 20 1000],[-30 -40 -50],'b','b');
synthetic=struct('schema_version',1,'points',[a b],'representative_index',1,'source','synthetic fixture');
[modeled,selection]=select_pn_profile(synthetic,150,'interpolate');
assert(isequal(modeled.f,[10 20 100]));
assert(modeled.kvco==3 && strcmp(selection.mode,'interpolate'));
assert(isequal(selection.indices,[1 2]) && isequal(selection.weights,[.5 .5]));
assert(abs(modeled.n(1)-10*log10((10^(-20/10)+10^(-30/10))/2))<1e-12);
expected_a=-20-10*log10(2);
assert(abs(modeled.n(2)-10*log10((10^(expected_a/10)+10^(-40/10))/2))<1e-12);
assert(~isempty(strfind(modeled.comment,'MODELED')));
assert(isequal(select_pn_profile(synthetic,100,'interpolate'),a));
ros_modeled=select_pn_profile(profile,1800e6,'interpolate');
assert(ros_modeled.fc==1800e6 && numel(ros_modeled.f)==4);

must_fail(@() select_pn_profile(synthetic,150),'pn_profile:NoExactPoint');
must_fail(@() select_pn_profile(synthetic,50,'interpolate'),'pn_profile:Extrapolation');
must_fail(@() select_pn_profile(synthetic,250,'interpolate'),'pn_profile:Extrapolation');
must_fail(@() select_pn_profile(synthetic,150,'nearest'),'pn_profile:InvalidMode');
bad=synthetic; bad.schema_version=2;
must_fail(@() validate_pn_profile(bad),'pn_profile:UnsupportedVersion');
bad=synthetic; bad.points(2).fc=100;
must_fail(@() validate_pn_profile(bad),'pn_profile:InvalidCarriers');
bad=synthetic; bad.points(1).f=[1 1 100];
must_fail(@() validate_pn_profile(bad),'pn_profile:InvalidOffsets');
bad=synthetic; bad.points(1).n=[NaN -20 -30];
must_fail(@() validate_pn_profile(bad),'');
bad=synthetic; bad.points(1).f=[1;10;100];
must_fail(@() validate_pn_profile(bad),'');
bad=synthetic; bad.representative_index=3;
must_fail(@() validate_pn_profile(bad),'');
bad=synthetic; bad.points(2).f=[100 200 1000];
must_fail(@() select_pn_profile(bad,150,'interpolate'),'pn_profile:NoCommonOffsets');
fprintf('pn_profile: ROS extraction, legacy MAT compatibility and interpolation tests passed.\n');
end

function run_example()
aa_generate_ros2100_example;
end

function must_fail(action,identifier)
failed=false;
try
    action();
catch exception
    failed=true;
    if ~isempty(identifier)
        assert(strcmp(exception.identifier,identifier),exception.message);
    end
end
assert(failed,'Expected an explicit failure.');
end

function cleanup_test(temporary,path_before,directory_before)
cd(directory_before);
path(path_before);
if exist(temporary,'dir')==7
    rmdir(temporary,'s');
end
end
